 External Refs:** Entry Points:********************************************************************************oldDataBank	equ 1theRTL	equ oldDataBank+1theResult	equ theRTL+3	phb	; save the old data bank		pea IdleWind>>8	; push the address of our databank on the stack	plb	plb	; set as the current data bank!		jsl ReallyOpen	; call the pascal open routine		lda idleWind	; return the opened window ptr	sta theResult,s	lda idleWind+2	sta theResult+2,s		plb	; restore the databank	RTL	EndP		EJECT********************************************************************************DAClose	PROC** Description:	Called in response to a DA close from the desk mgr*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	phb	; save the old data bank		pea IdleWind>>8	; push the address of our databank on the stack	plb	plb	; set as the current data bank!		jsl ReallyClose	; call the pascal open routine			plb	; restore the databank	RTL	EndP	EJECT********************************************************************************DAAction	PROC** Description:	Called in response to an Action or RUN event*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	phb	; save the old data bank		pea IdleWind>>8	; push the address of our databank on the stack	plb	plb	; set as the current data bank!		sta actionCode	; save the actionCode	stx eventP	; and event pointers	sty eventP+2		jsl ReallyAction	; call the pascal open routine		lda  quitFlag	; test the quit flag	beq @continue		Pushlong IdleWind	; close the DA	_CloseNDAByWinPtr@continue	lda actionCode	; return in <A> boolean flag		plb	; restore the databank	RTL	EndP	EJECT********************************************************************************DAInit	PROC** Description:	Called on Desk manager startup*** Inputs:	None** Outputs:	None** External Refs:** Entry Points:********************************************************************************	phb	; save the old data bank		pea IdleWind>>8	; push the address of our databank on the stack	plb	plb	; set as the current data bank!		sta ActionCode	; save the flag		jsl ReallyInit	; call the pascal open routine			plb	; restore the databank	RTL	EndP	END